<script setup lang="ts">
import { useRouter } from 'vue-router'
import { useUserStore } from '@/stores/user'
const fileRouter = useRouter(), fileUser = useUserStore()

import {moldSetPhones} from '@/utils/moldPresentation'
import CollaborationCell from '@/views/collaboration/components/CollaborationCell.vue'
import type { CellValue,CollaborationRow,PlanField } from '@/types/collaboration'
import type { MoldMasterOptions } from '@/types/molds'
const props=defineProps<{row:CollaborationRow;options:MoldMasterOptions;locked:boolean;reviewTarget?:boolean;value:(row:CollaborationRow,key:string)=>CellValue;dirty:(row:CollaborationRow,key:string)=>boolean}>()
const emit=defineEmits<{edit:[row:CollaborationRow,field:PlanField,text:string];preview:[row:CollaborationRow,field:PlanField,text:string];copy:[row:CollaborationRow];reason:[row:CollaborationRow];correction:[row:CollaborationRow,key:string];inventory:[row:CollaborationRow,part:string];unlink:[row:CollaborationRow,part:string]}>()
const basics=['setName','manufacturerName','ownerUserId','notes']
const parts=['pc','tpu'] as const
function field(key:string):PlanField {return props.options.moldFields.find(f=>f.key===key)||{key,label:({quoteAmount:'每套制模报价',quoteCurrency:'报价币种',quoteBasis:'报价依据'}as Record<string,string>)[key]||key,kind:key==='quoteAmount'?'money':key==='quoteCurrency'?'currency':'text',group:'engineering',maxLength:255}}
function confirmed(){return ['quoteAmount','quoteCurrency','quoteBasis'].some(k=>props.dirty(props.row,k))&&!props.dirty(props.row,'quoteConfirmed')?false:!!props.value(props.row,'quoteConfirmed')}
function can(f:PlanField){if(f.key.startsWith('quote'))return props.options.canWriteQuote;return props.options.writableGroups.some(group=>group===f.group)&&!(props.locked&&/OriginalMoldCode$/.test(f.key))}
</script>
<template>
  <section class="physical-card" :class="{'is-review-target':reviewTarget}" :data-mold-set-id="row.moldSetId"><header><strong>{{row.assetNumber}} · 第 {{row.setNo}} 套</strong><span v-if="reviewTarget" class="review-target">本次定位实物套</span><el-button v-if="fileUser.hasPermission('file:read')" link @click="fileRouter.push({path:'/files',query:{referenceType:'mold_set',referenceId:row.moldSetId,referenceName:row.setName,referenceCode:row.assetNumber}})">查看关联图纸</el-button><span v-if="row.sourceMoldSetId">来源套 #{{row.sourceMoldSetId}}</span><el-button v-if="options.writableGroups.includes('engineering')&&!row.schedulePaused" link @click="emit('copy',row)">复制 / 重新开模</el-button><el-button link @click="emit('reason',row)">更正 / 核对说明</el-button></header><p class="set-phones">本套适用手机：{{moldSetPhones(row)}}</p><p v-if="!options.writableGroups.includes('engineering')" class="hint">当前账号没有工程维护权限，实物核对状态只读；原刻码录入错误须由管理员更正并填写依据。</p><p v-else-if="locked" class="hint">原刻码已确认并锁定；可以继续核对实物状态与适配。原码录入错误请使用“更正录入错误”。</p>
    <div class="physical-fields"><label v-for="key in basics" :key="key"><span>{{field(key).label}}</span><CollaborationCell :field="field(key)" :value="value(row,key)" :editable="can(field(key))" :dirty="dirty(row,key)" :users="options.users" @preview="emit('preview',row,field(key),$event)" @edit="emit('edit',row,field(key),$event)"/></label></div>
    <div class="parts"><section v-for="part in parts" :key="part"><h4>{{part.toUpperCase()}} · {{row[part+'AssetNumber']}}</h4><label><span>{{part.toUpperCase()}} 完整原模具编码{{locked?'（已确认，锁定）':''}}</span><CollaborationCell :field="{...field(part+'OriginalMoldCode'),label:part.toUpperCase()+' 原模具编码'}" :value="value(row,part+'OriginalMoldCode')" :editable="can(field(part+'OriginalMoldCode'))" :dirty="dirty(row,part+'OriginalMoldCode')" @preview="emit('preview',row,field(part+'OriginalMoldCode'),$event)" @edit="emit('edit',row,field(part+'OriginalMoldCode'),$event)"/><el-button v-if="locked&&options.administrator" link @click="emit('correction',row,part+'OriginalMoldCode')">更正录入错误</el-button></label><p v-if="row[part+'CatalogMoldCode']" class="hint">已关联完整编码：{{row[part+'CatalogMoldCode']}}（注册表引用，原始记录保留）</p><label><span>实物核对状态</span><select :aria-label="part.toUpperCase()+' 实物核对状态'" :value="value(row,part+'PhysicalStatus')||'unknown'" :disabled="!options.writableGroups.includes('engineering')" @change="emit('edit',row,{...field(part+'PhysicalStatus'),kind:'text'},($event.target as HTMLSelectElement).value)"><option value="unknown">待核对</option><option value="making">在制</option><option value="confirmed">已确认实物</option></select></label><label v-for="suffix in ['CurrentLocation','LocationDetail']" :key="suffix"><span>{{suffix==='CurrentLocation'?'当前位置':'位置说明'}}</span><CollaborationCell :field="field(part+suffix)" :value="value(row,part+suffix)" :editable="can(field(part+suffix))" :dirty="dirty(row,part+suffix)" @preview="emit('preview',row,field(part+suffix),$event)" @edit="emit('edit',row,field(part+suffix),$event)"/></label><p class="hint">库存来源 {{row[part+'InventoryName']||'未关联'}}；不从 tooling 数量推算套数。</p><div v-if="options.writableGroups.includes('engineering')"><el-button link @click="emit('inventory',row,part)">人工确认来源资料</el-button><el-button v-if="row[part+'InventoryId']" link @click="emit('unlink',row,part)">解除来源关联</el-button></div></section></div>
    <section v-if="options.canReadQuote" class="quote"><h4>每套制模报价</h4><div class="physical-fields"><label v-for="key in ['quoteAmount','quoteCurrency','quoteBasis']" :key="key"><span>{{field(key).label}}</span><CollaborationCell :field="field(key)" :value="value(row,key)" :editable="can(field(key))" :dirty="dirty(row,key)" @preview="emit('preview',row,field(key),$event)" @edit="emit('edit',row,field(key),$event)"/></label></div><el-checkbox :model-value="confirmed()" :disabled="!options.canConfirmQuote" @change="emit('edit',row,{...field('quoteConfirmed'),kind:'boolean'},$event?'true':'false')">确认这套报价与依据</el-checkbox><p class="hint">报价与手机价格、预算、入账分开；空白代表未填写，零单独保留。已确认报价更正须填写更正原因，修改金额或依据后需重新确认。</p></section>
    <p v-else class="hint">没有报价查看权限。</p>
  </section>
</template>
<style scoped>.physical-card{max-width:1100px;box-sizing:border-box;border:1px solid #e1e7ef;border-radius:4px;padding:12px;margin-bottom:12px;font-size:12px}.is-review-target{border-color:#4d82ed;background:#f7faff}.review-target{color:#2c64a4}.physical-card header{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:10px}.physical-fields{display:grid;grid-template-columns:minmax(0,1fr);gap:12px}.physical-fields label:last-child:has(textarea){grid-column:1/-1}label{display:block;min-width:0;margin-bottom:8px}label>span{display:block;margin-bottom:4px;color:#294f75;font-weight:600}.parts{display:grid;grid-template-columns:minmax(0,1fr);gap:12px}.parts>section{background:#f8fafc;padding:10px;min-width:0}h4{font-size:12px;margin:8px 0}.hint{font-size:12px;color:#7c8a9b;line-height:1.5}.quote{border-top:1px solid #e4eaf1;padding-top:4px}select{width:100%;height:28px;background:white;border:1px solid #dbe4ef;font:inherit;border-radius:3px}.physical-card :deep(.readonly-value){display:block;overflow:visible;-webkit-line-clamp:unset}.physical-card :deep(.plan-cell){min-height:28px;font-size:12px}.physical-card :deep(input),.physical-card :deep(select),.physical-card :deep(textarea){padding:5px 8px;background:#f8fbff;color:#243f5d;border:1px solid #bdcfe2;border-radius:3px}.physical-card :deep(input:focus),.physical-card :deep(select:focus),.physical-card :deep(textarea:focus){outline:2px solid #93b8e7;outline-offset:1px}@media(max-width:760px){.parts,.physical-fields{grid-template-columns:1fr}}</style>
